/** Contextual purchase history. Receipt, invoice and payment retain separate authority. */
import {e,link,Header} from './components.js';
import {financeAmount,financeDate,financeNumber} from './finance-connected.js';
const kinds={receipt:'Приход',transfer:'Перемещение',application:'Внесение',writeoff:'Списание',plan:'План'};
const states={draft:'Черновик',posted:'Подтверждено',reversed:'Отменено обратным движением',READY:'Готово к проверке',NEEDS_INPUT:'Нужно уточнить',POSTED:'Подтверждено',CONFIRMED_NONPOSTING:'Связь подтверждена',REJECTED:'Отклонено',DEFERRED:'Отложено'};
const card=s=>`<section class="card purchase-card">${s}</section>`;
const note=s=>`<p class="note">${e(s)}</p>`;
const fact=(label,value)=>`<div class="purchase-fact"><span>${e(label)}</span><strong>${e(value)}</strong></div>`;
const q=(v,u)=>v==null?'Неизвестно':financeNumber(v)+' '+(u||'единица не указана');
export function historySelection(route){const [page,from='all',to='all',product='all',location='all',supplier='all',kind='all',offset='0']=route.split('/');return {page:page==='purchases'?'purchases':'stock-history',date_from:from==='all'?'':from,date_to:to==='all'?'':to,product_id:product==='all'?'':product,location_id:location==='all'?'':location,supplier_id:supplier==='all'?'':supplier,kind:kind==='all'?'':kind,offset:/^\d+$/.test(offset)?Number(offset):0};}
export function historyRoute(f,changes={}){const x={...f,...changes};return [x.page,x.date_from||'all',x.date_to||'all',x.product_id||'all',x.location_id||'all',x.supplier_id||'all',x.kind||'all',x.offset||0].join('/');}
export function historyQuery(f){const p=new URLSearchParams({offset:String(f.offset),limit:'20'});for(const key of ['date_from','date_to','product_id','location_id','supplier_id'])if(f[key])p.set(key,f[key]);if(f.page==='stock-history'&&f.kind)p.set('kind',f.kind);return p.toString();}
function choose(label,name,rows,value){return `<label>${e(label)}<select name="${e(name)}"><option value="">Все</option>${rows.map(r=>`<option value="${e(r.id)}" ${r.id===value?'selected':''}>${e(r.name)}</option>`).join('')}</select></label>`;}
function filters(r,f){return `<form data-form="history-filters" class="purchase-filters"><label>С даты<input name="date_from" type="date" value="${e(f.date_from)}"></label><label>По дату включительно<input name="date_to" type="date" value="${e(f.date_to)}"></label>${choose('Товар','product_id',r.available_products,f.product_id)}${choose('Место хранения','location_id',r.available_locations,f.location_id)}${choose('Поставщик','supplier_id',r.available_suppliers,f.supplier_id)}${f.page==='stock-history'?choose('Вид движения','kind',Object.entries(kinds).map(([id,name])=>({id,name})),f.kind):''}<button class="btn secondary" type="submit">Показать историю</button><div class="form-error" role="alert"></div></form>`;}
export function purchaseOriginal(o){return `<details class="source-provenance"><summary>Оригинал и происхождение</summary>${o.structured_original?note('Самостоятельная форма владельца · '+o.structured_original.form_id)+Object.entries(o.structured_original.fields).map(([k,v])=>fact(({event_date:'Дата в форме',original_product_name:'Товар',quantity:'Количество',unit:'Единица',location_id:'Склад',destination_id:'Куда',notes:'Заметка',product_id:'Идентификатор товара'})[k]||k,v||'Не указано')).join(''):o.raw_text?`<p class="source-text">${e(o.raw_text)}</p>`:note('Текст не добавлялся.')}${o.has_file&&o.original_url?`<a class="btn secondary" href="${e(o.original_url)}" download>${e(o.filename||'Скачать оригинал')}</a>`:''}${o.sha256?note('SHA-256: '+o.sha256):''}${note(o.source+(o.locator?' · '+o.locator:''))}</details>`;}
function lines(rows){return rows.map(l=>`<article class="purchase-line"><h3>${e(l.original_product_name)}</h3>${fact('Количество',q(l.quantity,l.unit))}${fact('Место',l.location_name||'Не указано')}${l.destination_id?fact('Куда',l.destination_name||'Не установлено'):''}${fact('Стоимость за единицу',financeAmount(l.unit_cost,l.currency))}${l.base_quantity!=null&&l.base_unit!==l.unit?note('По подтверждённому правилу: '+q(l.base_quantity,l.base_unit)):''}</article>`).join('');}
function eventCard(v,to){return card(`${to?link(`<strong>${e(kinds[v.kind])} · ${e(financeDate(v.event_date))}</strong><span class="tag">${e(states[v.status]||v.status)}</span>`,to,'list-row'):`<div class="list-row"><strong>${e(kinds[v.kind])} · ${e(financeDate(v.event_date))}</strong><span>${e(states[v.status]||v.status)}</span></div>`}${lines(v.lines)}${v.supplier_name?note('Поставщик: '+v.supplier_name):''}${v.replacement_id?link('Открыть исправление','receipt/'+v.replacement_id,'btn secondary'):''}${v.replacement_of_id?link('Предыдущая версия','receipt/'+v.replacement_of_id,'btn secondary'):''}`);}
function movements(rows){return `<h2>Физические движения</h2>${rows.map(m=>`<article class="purchase-line">${fact(m.product_name,q(m.quantity,m.base_unit))}${fact('Место',m.location_name)}${fact('Без известной стоимости',q(m.uncosted_quantity,m.base_unit))}${fact('Известная часть стоимости',financeAmount(m.known_cost,m.currency))}${note(financeDate(m.event_date)+(m.reversal_of_seq?' · обратное движение':'')+' · №'+m.seq)}</article>`).join('')||note('Движений нет. Черновик или план не изменяет склад.')}`;}
export function purchaseHistoryView(r,f){const purchases=f.page==='purchases',rows=purchases?r.items:r.events;return Header(purchases?'Покупки и поставки':'История склада',purchases?'Приход, документ, долг и оплата':'События и движения по товару и месту',true)+`<div class="page-actions">${link('Товар привезли','quick/receipt','btn primary')}${link(purchases?'Все движения':'Покупки',purchases?'stock-history':'purchases','btn secondary')}${link('Переместить','quick/transfer','btn secondary')}</div>`+filters(r,f)+note('Период отбирает дату исходного события. Дата обратного движения и история исправлений показаны внутри события.')+note('Начальные остатки не подтверждены. Журнал движений не доказывает полный физический остаток. Неизвестная стоимость не равна нулю.')+(!purchases?card(`<h2>Учтённая позиция сейчас</h2>${note('По выбранным товару и месту, по всем датам. Это не начальный остаток периода и не физическая инвентаризация.')}${r.stock.map(x=>`<article class="purchase-line"><h3>${e(x.product_name)}</h3>${fact(x.location_name,q(x.quantity,x.base_unit))}${fact('Без стоимости',q(x.uncosted_quantity,x.base_unit))}${fact('Известная часть стоимости',financeAmount(x.known_cost,x.currency))}</article>`).join('')||note('Учтённых движений нет. Начальная позиция неизвестна.')}`):'')+rows.map(v=>eventCard(v,purchases?'purchase/'+v.id+'/'+encodeURIComponent(historyRoute(f)):'stock-event/'+v.id+'/'+encodeURIComponent(historyRoute(f)))).join('')+(!rows.length?card(note('По выбранным условиям событий нет.')):'')+`<nav class="page-actions" aria-label="Страницы истории">${f.offset?link('Предыдущие',historyRoute(f,{offset:Math.max(0,f.offset-20)}),'btn secondary'):''}${r.next_offset!=null?link('Следующие',historyRoute(f,{offset:r.next_offset}),'btn secondary'):''}</nav>${note('Всего событий: '+r.total)}`;}
function debtDocument(d,back){return `<article class="purchase-line"><h3>${e(d.source.description||'Связанный документ')}</h3>${fact('Сумма всего документа',financeAmount(d.original_amount,d.currency))}${fact('Погашено',financeAmount(d.allocated_amount,d.currency))}${fact('Остаток документа сейчас',financeAmount(d.remaining_amount,d.currency))}${link('Документ и оплаты','money-document/'+d.obligation_id+'/'+encodeURIComponent(back),'btn secondary')}${note('Документ может относиться к нескольким приходам. Его сумма не является стоимостью этой строки склада.')}</article>`;}
export function purchaseDetailView(v,back='purchases'){return Header('История поставки',financeDate(v.event_date),true)+eventCard(v,'receipt/'+v.id)+card(purchaseOriginal(v.original))+card(`<h2>Документы и отдельные действия</h2>${v.status==='posted'?link('Добавить счёт к приходу','invoice-new/'+v.id,'btn primary'):note('Сначала нужен подтверждённый физический приход. Счёт не проводит его повторно.')}${v.pending_invoice_actions.map(w=>`<article class="purchase-line"><strong>${e(w.filename||'Исходная запись счёта')}</strong>${note(w.invoice_intent==='existing_payable'?'Связь с существующим долгом':'Счёт на операционный расход')}${note(w.proposals.map(p=>states[p.state]||p.state).join(' · ')||'Источник сохранён · подготовка '+w.job_state)}${w.proposals.some(p=>p.action_type==='INVOICE_MATCH'&&p.current_receipt_id&&p.current_receipt_id!==v.id)?note('В текущей ревизии выбран другой приход. Исходный контекст сохранён.'):''}${link('Открыть документ и проверку','invoice-source/'+(w.proposals.find(p=>p.action_type==='INVOICE_MATCH')?.current_receipt_id||v.id)+'/'+w.source_id,'btn secondary')}</article>`).join('')}${v.invoice_links.map(l=>`<article class="purchase-line">${note('Явная связь подтверждена '+financeDate(l.created_at))}${link('Оригинал счёта','source/'+l.original_source_id,'btn secondary')}${l.supplier_consistency==='LEGACY_MISMATCH'?note('Историческое несоответствие поставщика. Связь не была переписана.'):''}${!l.finance_obligation_id?note('Архивная связь без финансового документа. Долг не был создан.'):''}</article>`).join('')}${note('Прикрепление счёта не создаёт второй приход и не устанавливает неизвестную стоимость товара.')}`)+card(`<h2>Долги и оплаты</h2>${v.supplier_id&&v.finance_obligation_id&&v.linked_documents.some(d=>d.obligation_id===v.finance_obligation_id&&d.counterparty_id!==v.supplier_id)?note('Историческая прямая финансовая ссылка указывает другого поставщика. Исходные записи сохранены; соответствие не подтверждено.'):''}${v.linked_documents.map(d=>debtDocument(d,'purchase/'+v.id+'/'+encodeURIComponent(back))).join('')||note('Связанного финансового документа нет. Из физического прихода долг и оплата не выводятся.')}`)+card(movements(v.movements))+`<div class="page-actions">${link('Назад к истории',back,'btn secondary')}${link('К складу','inventory','btn secondary')}</div>`;}
export function stockEventView(v,back='stock-history'){return Header(kinds[v.kind]||'Складское событие',states[v.status]||v.status,true)+eventCard(v,['receipt','transfer'].includes(v.kind)?'receipt/'+v.id:null)+card(purchaseOriginal(v.original))+card(movements(v.movements))+(v.kind==='receipt'?link('История поставки','purchase/'+v.id,'btn primary'):'')+`<div class="page-actions">${link('Назад к истории',back,'btn secondary')}</div>`;}

export function invoiceTargetMatches(receiptId,source,match){return match?.revision?.payload?.receipt_id ? match.revision.payload.receipt_id===receiptId : source.invoice_receipt_id===receiptId;}
